27	        if (lectureId) {
28	            return this.lectureService.find(lectureId).pipe(
29	                filter((response: HttpResponse<Lecture>) => response.ok),
30	                map((lecture: HttpResponse<Lecture>) => lecture.body!),
31	            );
32	        }
33	        return of(new Lecture());
34	    }
35	}
