8	})
9	export class LectureTitleChannelNameComponent implements OnInit {
10	    @Input() lecture: Lecture;
11	
12	    hideChannelNameInput = false;
13	    ngOnInit() {
14	        this.hideChannelNameInput = !this.requiresChannelName(this.lecture);
15	    }
16	
17	    /**
18	     * Determines whether the provided lecture should have a channel name. This is not the case, if messaging in the course is disabled.
19	     * If messaging is enabled, a channel name should exist for newly created and imported lectures.
20	     *
21	     * @param lecture the lecture under consideration
22	     * @return boolean true if the channel name is required, else false
23	     */
24	    private requiresChannelName(lecture: Lecture): boolean {
25	        // not required if messaging and communication is disabled
26	        if (!isCommunicationEnabled(lecture.course)) {
27	            return false;
28	        }
29	
30	        // required on create (messaging is enabled)
31	        if (lecture.id === undefined) {
32	            return true;
33	        }
34	
35	        // when editing, it is required if the lecture has a channel
36	        return lecture.channelName !== undefined;
37	    }
38	}
